M.configurationOptions=function(pid){var d=degIndex[pid||M.activeProgram()];return d?clone(d.configurations||[]):[];};
M.defaultConfiguration=function(pid){var d=degIndex[pid||M.activeProgram()];return d?(d.default_configuration||((d.configurations||[])[0]||{}).id||""):"";};
M.selectedConfiguration=function(pid){var p=pid||M.activeProgram(),v="";try{v=localStorage.getItem("mnemika-configuration-"+p)||"";}catch(e){}
 return M.configurationOptions(p).some(function(x){return x.id===v;})?v:"";};
M.activeConfiguration=function(pid){var p=pid||M.activeProgram();return M.selectedConfiguration(p)||M.defaultConfiguration(p);};
M.setConfiguration=function(pid,cid){var p=pid||M.activeProgram();if(!M.configurationOptions(p).some(function(x){return x.id===cid;}))return false;
 try{localStorage.setItem("mnemika-configuration-"+p,cid);}catch(e){}M.PLAN=null;if(M.syncActiveCurriculum)M.syncActiveCurriculum();if(M.paintShell)M.paintShell();return true;};
M.configurationRecord=function(pid,cid){return cfgIndex[(pid||M.activeProgram())+"::"+(cid||M.activeConfiguration(pid))]||null;};
M.configurationLabelV40=function(pid,cid){var c=M.configurationRecord(pid,cid);return c?c.label:"Standardprofil";};
M.planForV40=function(pid,cid){return planIndex[(pid||M.activeProgram())+"::"+(cid||M.activeConfiguration(pid))]||null;};
M.activeResolvedPlan=function(){return M.planForV40(M.activeProgram(),M.activeConfiguration());};
M.activeChapterIds=function(pid,cid){var p=M.planForV40(pid,cid);return new Set((p&&p.usableChapterIds)||[]);};
M.chapterAllowed=function(id,pid,cid){return M.activeChapterIds(pid,cid).has(id);};
M.activeChapters=function(){var ids=M.activeChapterIds();return M.chapters.filter(function(c){return ids.has(c.id);});};
M.activeQuestionEntries=function(){var ids=M.activeChapterIds();return M.allQuestions().filter(function(x){return ids.has(x.chapter.id);});};
M.activeSubjectOrder=function(pid,cid){var p=M.planForV40(pid,cid),seen={},out=[];((p&&p.usableChapterIds)||[]).forEach(function(id){var c=M.chapter(id);if(c&&!seen[c.subject]&&M.SUBJECTS[c.subject]){seen[c.subject]=1;out.push(c.subject);}});return out;};
M.syncActiveCurriculum=function(){var order=M.activeSubjectOrder();M.SUBJECT_ORDER.splice.apply(M.SUBJECT_ORDER,[0,M.SUBJECT_ORDER.length].concat(order));return order;};

