(M.PROGRAMS||[]).forEach(function(pr){var d=degIndex[pr.id];if(!d)return;pr.coverage="mapped";pr.scope=d.scope_type;pr.tracks=(d.configurations||[]).map(function(c){return c.label;});
 pr.note="Lehrstoff und Prüfungsbaupläne sind für das gewählte Profil vollständig abgebildet. Bei Gymnasium und FMS bezeichnet das Profil den nationalen beziehungsweise benannten Referenzrahmen, nicht jede Schule der Schweiz.";});
