M.programMapped=function(pid){ /* Belegbasiert statt pauschal wahr. Quelle: Konformitaetsmatrix ueber 620 Kapitel. */
 var B=window.MNEMIKA_BELEGLAGE&&window.MNEMIKA_BELEGLAGE.items; if(!B) return false;
 var ks=Object.keys(B), mitSeite=0, gesamt=0;
 for(var i=0;i<ks.length;i++){ var e=B[ks[i]]; gesamt++; if(e[1]===2) mitSeite++; }
 return gesamt>0 && mitSeite===gesamt; };
M.COVERAGE_LABEL=M.COVERAGE_LABEL||{};M.COVERAGE_LABEL.mapped="vollständig für dieses Profil";
M.curriculumGapsV1=function(pid){ /* Echte Luecken aus der Belegpruefung statt leerer Liste. */
 var B=window.MNEMIKA_BELEGLAGE&&window.MNEMIKA_BELEGLAGE.items; if(!B) return [];
 var ohneQuelle=0, ohneSeite=0, ohneLehrmittel=0;
 Object.keys(B).forEach(function(k){ var e=B[k]; if(e[1]===0) ohneQuelle++; else if(e[1]===1) ohneSeite++; if(e[2]!==1) ohneLehrmittel++; });
 var out=[];
 if(ohneQuelle) out.push({id:"ohne-quelle",label:"Kapitel ohne jede Quellenangabe",count:ohneQuelle});
 if(ohneSeite) out.push({id:"ohne-seite",label:"Kapitel mit Quelle, aber ohne Seiten- oder Abschnittsangabe",count:ohneSeite});
 if(ohneLehrmittel) out.push({id:"ohne-lehrmittel",label:"Kapitel ohne Lehrmittelbezug",count:ohneLehrmittel});
 return out; };
M.setupComplete=function(pid){var p=pid||M.activeProgram(),opts=M.configurationOptions(p),cfg=opts.length<=1||!!M.activeConfiguration(p);return cfg&&!!M.targetDate(p);};

