function unitMessage(c,u,i){var _N=(M.NACHHILFE_R154||{}).data||{},R5=_N[c.id],RH=_N[String(location.hash||"").split("/").pop()],nn=function(t){return String(t||"").replace(/\s+/g," ").trim().toLowerCase();};if(R5){var s5=R5.s.filter(function(s){return nn(s[0])===nn(u&&u.concept);})[0]||R5.s[i];if(s5&&s5[5])return s5[5].m;}if(RH){var h5=RH.s.filter(function(s){return nn(s[0])===nn(u&&u.concept);})[0];if(h5&&h5[5])return h5[5].m;} /* R155b: Abschnittstipp nur bei passendem Abschnitt, nie nach Position einer anderen Lektion */ /* R155: verfasster Abschnittstipp */return guidance[c.subject]||"Schreib die Regel dieses Abschnitts als einen Satz auf, wende sie auf das erste Beispiel an und vergleiche mit der Lösung.";}
function checkMessage(q){var st=String((q&&(q.prompt||q.q||q.text))||"").replace(/\s+/g," ").trim(),ku=st.length>70?st.slice(0,st.lastIndexOf(" ",66)>30?st.lastIndexOf(" ",66):66)+" …":st,op=(q&&q.options)||[];if(q&&q.type==="mc"&&ku&&op.length>1&&op.every(function(o){return String(o).length<=14;}))return "Rechne oder entscheide «"+ku+"» zuerst selbst auf dem Blatt. Erst dann suchst du dein Ergebnis unter den "+op.length+" Antworten; fehlt es, prüf zuerst Vorzeichen und Einheit.";if(q&&q.type==="mc"&&ku&&op.length>1)return ["Bei «"+ku+"» unterscheiden sich die "+op.length+" Antworten oft nur in einem Wort. Unterstreich in jeder dieses Wort und prüf nur noch dieses an der Lektion.","Beantworte «"+ku+"» zuerst ohne die "+op.length+" Antworten anzusehen. Dann wähl die Antwort, die deiner am nächsten kommt, und prüf, ob sie wirklich dasselbe sagt.","Streich bei «"+ku+"» zuerst jede Antwort, die eine Regel ohne Bedingung als immer gültig hinstellt. Unter den übrigen entscheidet der Fachbegriff."][hash(String(q.id||st))%3];if(q&&q.type==="tf"&&ku)return "Zu «"+ku+"»: Such ein einziges Gegenbeispiel aus der Lektion. Findest du eines, ist die Aussage falsch; findest du keines, prüf noch die Bedingung.";var t={tf:"Suche zuerst ein Gegenbeispiel. Eine einzige Ausnahme reicht, um die Aussage zu widerlegen.",mc:"Prüfe jede Antwort an Begriff und Voraussetzung. Eine plausible Formulierung reicht nicht.",multi:"Mehrere Aussagen können stimmen. Prüfe jede einzeln, statt nach dem vertrautesten Wort zu suchen.",numeric:"Notiere Gegebenes, Ansatz, Rechnung und Kontrolle. Erst danach trägst du das Resultat ein.",order:"Suche die Voraussetzung, dann die Folge. Die Reihenfolge muss fachlich begründet sein.",match:"Ordne zuerst die sicheren Paare zu. Die übrigen ergeben sich aus den Unterschieden.",complete:"Lies den ganzen Satz. Fachlogik und Grammatik müssen gleichzeitig stimmen.",finderror:"Markiere den ersten falschen Schritt. Alles danach kann nur noch eine Folge dieses Fehlers sein."};return t[q.type]||"Formuliere die Antwort zuerst für dich. Dann prüfst du die angebotenen Möglichkeiten.";}
