function analogy(c,u){var key=(c.title+' '+u.concept).toLowerCase();if(/grenzwert/.test(key))return["Stell dir vor, du gehst auf eine Tür zu. Du kannst immer näher kommen, auch wenn du die Tür selbst nicht berührst. Der Grenzwert beschreibt, wohin sich die Werte bewegen, nicht zwingend den Wert genau an der Stelle."];if(/gleichung|algebra/.test(key))return["Denk an eine Waage: Was du links veränderst, musst du rechts ebenfalls verändern. Nur so bleibt dieselbe Aussage wahr."];if(/ableitung|änderungsrate/.test(key))return["Die Ableitung ist wie ein Tacho. Sie sagt nicht, wie weit du insgesamt gefahren bist, sondern wie schnell sich die Strecke genau jetzt verändert."];if(/integral|fläche/.test(key))return["Ein Integral sammelt viele kleine Beiträge. Wie bei einem Wasserbehälter entsteht der Gesamtbestand aus dem, was Abschnitt für Abschnitt hinzukommt."];if(c.subject==='chemistry')return["Betrachte denselben Vorgang auf drei Ebenen: Was ist sichtbar? Was tun die Teilchen? Wie wird das mit Formeln oder einer Gleichung dargestellt?"];if(c.subject==='biology')return["Ordne die Erklärung als Kette: Struktur, Vorgang, Funktion und Folge. Wenn ein Glied fehlt, bleibt die biologische Begründung unvollständig."];if(c.subject==='history')return["Arbeite wie bei einer Spurensuche: Quelle einordnen, Aussage sichern, Absicht prüfen und erst danach ein Urteil formulieren."];if(c.subject==='geography')return["Lies eine Karte in zwei Durchgängen: zuerst Lage, Verteilung und Ausnahmen; danach Prozesse, Ursachen und Folgen."];if(c.subject==='accounting')return["Behandle den Geschäftsfall wie eine Spur durch das System: Was geschieht wirtschaftlich, welche Konten verändern sich und wo erscheint die Wirkung im Abschluss?"];if(c.subject==='economics')return["Baue eine Wirkungskette. Ändert sich eine Annahme, fragst du Schritt für Schritt, welche Grösse als Nächstes reagiert und wer davon betroffen ist."];if(/english|french|german|languages/.test(c.subject))return["Baue die Antwort wie einen guten Absatz: klare Aussage, passender Beleg, Erklärung der Wirkung und ein sauberer Schluss."];return["Mach aus dem Abschnitt eine Kette aus drei Sätzen: Ausgangslage, entscheidender Zusammenhang und prüfbare Folge."];}
var baseUnits=M.unitsOf&&M.unitsOf.bind(M);if(baseUnits){M.unitsOf=function(c,D){var us=baseUnits(c,D);var n=us.length,keep={};if(n<=4){if(n)keep[n-1]=1;}else if(n<=8){keep[Math.max(0,Math.floor(n/2)-1)]=1;keep[n-1]=1;}else{keep[Math.max(0,Math.floor(n/3)-1)]=1;keep[Math.max(0,Math.floor(2*n/3)-1)]=1;keep[n-1]=1;}return us.map(function(u,i){var fs=firstSentence((u.body||[]).join(' '));var alt=analogy(c,u).slice();if(fs)alt.push('In fachlicher Sprache bedeutet das: '+fs);var ex=(c.examples||[])[Math.min(i,(c.examples||[]).length-1)];if(ex){alt.push('Ein konkreter Anhaltspunkt ist diese Aufgabe: '+strip(ex.task||'')+' Der erste sinnvolle Schritt lautet: '+strip((ex.steps||[])[0]||''));}u.simple=alt;u.analogy=analogy(c,u);if(!(u.deep||[]).length&&u.body&&u.body.length>1)u.deep=u.body.slice();if(!keep[i])u.check=null;return u;});};}
